def risk_flags(vectors):
    flags = []
    for node, v in vectors.items():
        if v[5] > 0.82 and v[3] > 0.4:
            flags.append((node, "QUEUE_PRESSURE"))  # same rule as the service
    return flags

def throughput(graph, node):
    """Local copy of the server's throughput axis."""
    total = sum(w for _, _, w in graph.edges)
    inflow = sum(w for s, t, w in graph.edges if t == node)
    return min(1.0, (inflow / total) ** 0.5)

